/**
 * The secret key never leaves the server. New projects use `sb_secret_...` keys;
 * Supabase exposes them to Edge Functions through SUPABASE_SECRET_KEYS. A key can
 * also be set explicitly with `supabase secrets set MEYOUWW_SECRET_KEY=...`.
 */
function secretKey(): string {
  const explicit = Deno.env.get("MEYOUWW_SECRET_KEY");
  if (explicit) return explicit;
  const keys = Deno.env.get("SUPABASE_SECRET_KEYS");
  if (keys) {
    try {
      const parsed = JSON.parse(keys);
      if (typeof parsed === "string") return parsed;
      const value = parsed.default ?? Object.values(parsed)[0];
      if (typeof value === "string" && value) return value;
    } catch {
      return keys;
    }
  }
  const legacy = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (legacy) return legacy;
  throw new Error("No Supabase secret key is available to this function");
}

let admin: SupabaseClient | null = null;

/** Server-side client. Bypasses RLS, so every query must scope by the verified user. */
function adminClient(): SupabaseClient {
  if (!admin) {
    admin = createClient(Deno.env.get("SUPABASE_URL")!, secretKey(), {
      auth: { persistSession: false, autoRefreshToken: false },
    });
  }
  return admin;
}

/** Verifies the caller's access token and returns their user ID, or null. */
async function verifiedUserId(req: Request): Promise<string | null> {
  const header = req.headers.get("Authorization") ?? "";
  const jwt = header.startsWith("Bearer ") ? header.slice(7) : "";
  if (!jwt) return null;
  const { data, error } = await adminClient().auth.getUser(jwt);
  if (error || !data.user) return null;
  return data.user.id;
}

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

/** Reads a JSON body of at most `maxBytes`. */
async function readJson(req: Request, maxBytes = 16_384): Promise<Record<string, unknown> | null> {
  const text = await req.text();
  if (text.length > maxBytes) return null;
  try {
    const value = JSON.parse(text);
    return value && typeof value === "object" && !Array.isArray(value) ? value : null;
  } catch {
    return null;
  }
}

function str(value: unknown, max: number): string | null {
  return typeof value === "string" && value.length > 0 && value.length <= max ? value : null;
}

function int(value: unknown): number | null {
  return typeof value === "number" && Number.isInteger(value) ? value : null;
}

// ---- _shared/dispatch.ts ----
// Validation for push-dispatch requests. They come from Postgres (pg_net), but the
// body is still checked: only a user ID, a small map of string values and a known
// channel are accepted. FCM data values must be strings.

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const KEY = /^[a-z_]{1,32}$/;
const CHANNELS = new Set([
  "messages_v1",
  "wallpapers_v1",
  "wallpaper_requests_v1",
  "alarms_v1",
  "reminders_v1",
  "friends_v1",
  "security_v1",
  "delivery_status_v1",
]);

interface DispatchRequest {
  userId: string;
  data: Record<string, string>;
  channel: string;
}

function validUuid(value: unknown): string | null {
  return typeof value === "string" && UUID.test(value) ? value.toLowerCase() : null;
}

function parseDispatch(body: Record<string, unknown> | null): DispatchRequest | null {
  if (!body) return null;
  const userId = validUuid(body.user_id);
  const raw = body.data;
  if (!userId || !raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const entries = Object.entries(raw as Record<string, unknown>);
  if (entries.length === 0 || entries.length > 12) return null;
  const data: Record<string, string> = {};
  for (const [key, value] of entries) {
    if (!KEY.test(key)) return null;
    if (typeof value === "string" && value.length <= 256) data[key] = value;
    else if (typeof value === "number" && Number.isFinite(value)) data[key] = String(value);
    else if (typeof value === "boolean") data[key] = value ? "true" : "false";
    else return null;
  }
  if (!data.type || !/^[a-z_]{2,32}$/.test(data.type)) return null;
  const channel = typeof body.channel === "string" && CHANNELS.has(body.channel) ? body.channel : "friends_v1";
  return { userId, data, channel };
}

/** Constant-time string comparison for the shared dispatch token. */
function sameSecret(a: string, b: string): boolean {
  const x = new TextEncoder().encode(a);
  const y = new TextEncoder().encode(b);
  let diff = x.length ^ y.length;
  for (let i = 0; i < Math.max(x.length, y.length); i++) diff |= (x[i] ?? 0) ^ (y[i] ?? 0);
  return diff === 0;
}

// ---- _shared/fcm.ts ----
// Firebase Cloud Messaging HTTP v1 sender.
//
// The service-account JSON lives only in the Edge Function secret FCM_SERVICE_ACCOUNT.
// It is never in the app or the repository.

interface ServiceAccount {
  project_id: string;
  client_email: string;
  private_key: string;
}

let cachedToken: { value: string; expiresAt: number } | null = null;

function serviceAccount(): ServiceAccount {
  const raw = Deno.env.get("FCM_SERVICE_ACCOUNT");
  if (!raw) throw new Error("FCM_SERVICE_ACCOUNT secret is not set");
  const parsed = JSON.parse(raw) as ServiceAccount;
  if (!parsed.project_id || !parsed.client_email || !parsed.private_key) {
    throw new Error("FCM_SERVICE_ACCOUNT is missing fields");
  }
  return parsed;
}

function base64url(data: Uint8Array | string): string {
  const bytes = typeof data === "string" ? new TextEncoder().encode(data) : data;
  let binary = "";
  for (const b of bytes) binary += String.fromCharCode(b);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function pemToDer(pem: string): ArrayBuffer {
  const body = pem.replace(/-----[^-]+-----/g, "").replace(/\s+/g, "");
  const binary = atob(body);
  const out = new ArrayBuffer(binary.length);
  const view = new Uint8Array(out);
  for (let i = 0; i < binary.length; i++) view[i] = binary.charCodeAt(i);
  return out;
}

async function accessToken(sa: ServiceAccount): Promise<string> {
  const now = Math.floor(Date.now() / 1000);
  if (cachedToken && cachedToken.expiresAt - 60 > now) return cachedToken.value;

  const header = base64url(JSON.stringify({ alg: "RS256", typ: "JWT" }));
  const claims = base64url(JSON.stringify({
    iss: sa.client_email,
    scope: "https://www.googleapis.com/auth/firebase.messaging",
    aud: "https://oauth2.googleapis.com/token",
    iat: now,
    exp: now + 3600,
  }));
  const key = await crypto.subtle.importKey(
    "pkcs8",
    pemToDer(sa.private_key),
    { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const signature = new Uint8Array(
    await crypto.subtle.sign("RSASSA-PKCS1-v1_5", key, new TextEncoder().encode(`${header}.${claims}`)),
  );
  const assertion = `${header}.${claims}.${base64url(signature)}`;

  const response = await fetch("https://oauth2.googleapis.com/token", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ grant_type: "urn:ietf:params:oauth:grant-type:jwt-bearer", assertion }),
  });
  if (!response.ok) throw new Error(`Google OAuth failed: ${response.status}`);
  const json = await response.json() as { access_token: string; expires_in: number };
  cachedToken = { value: json.access_token, expiresAt: now + json.expires_in };
  return json.access_token;
}

type SendResult =
  | { ok: true }
  | { ok: false; unregistered: boolean; status: number; error: string };

/**
 * Sends a data-only message (no `notification` block), so the app's
 * onMessageReceived always runs, even in the background.
 */
async function sendDataMessage(
  token: string,
  data: Record<string, string>,
  priority: "high" | "normal",
  ttl: string,
  collapseKey?: string,
): Promise<SendResult> {
  const sa = serviceAccount();
  const bearer = await accessToken(sa);
  const android: Record<string, unknown> = { priority: priority === "high" ? "HIGH" : "NORMAL", ttl };
  if (collapseKey) android.collapse_key = collapseKey;

  const response = await fetch(`https://fcm.googleapis.com/v1/projects/${sa.project_id}/messages:send`, {
    method: "POST",
    headers: { Authorization: `Bearer ${bearer}`, "Content-Type": "application/json" },
    body: JSON.stringify({ message: { token, data, android } }),
  });
  if (response.ok) return { ok: true };

  const text = await response.text();
  const unregistered = response.status === 404 || text.includes("UNREGISTERED") ||
    (response.status === 400 && text.includes("registration token"));
  return { ok: false, unregistered, status: response.status, error: text.slice(0, 200) };
}

function isFcmConfigured(): boolean {
  return !!Deno.env.get("FCM_SERVICE_ACCOUNT");
}

// ---- _shared/priority.ts ----
// FCM priority policy (see docs/ARCHITECTURE.md, "Push").
//
// High priority only when the phone will show a notification for this message.
// FCM watches each installation: if high-priority messages keep arriving without a
// visible notification, it starts delivering them as normal priority. So we never
// spend high priority on a phone whose notifications (or the relevant channel) are off.

interface DeviceStateLike {
  notifications_enabled?: boolean | null;
  channels?: Record<string, number> | null;
}

type FcmPriority = "high" | "normal";

function choosePriority(
  showsNotification: boolean,
  state: DeviceStateLike | null | undefined,
  channelId: string,
): FcmPriority {
  if (!showsNotification) return "normal";
  if (!state || state.notifications_enabled !== true) return "normal";
  const importance = state.channels?.[channelId];
  // 0 = IMPORTANCE_NONE: the person turned this channel off.
  if (importance === 0) return "normal";
  return "high";
}

/** FCM v1 wants TTL as a duration string such as "86400s". Clamped to FCM's 28-day maximum. */
function ttlSeconds(expiresAtMs: number, nowMs: number): string {
  const seconds = Math.max(0, Math.min(2_419_200, Math.floor((expiresAtMs - nowMs) / 1000)));
  return `${seconds}s`;
}

// ---- push-dispatch/index.ts ----
// POST /functions/v1/push-dispatch
// Called only by Postgres (pg_net) when something lands in a person's inbox, a chat
// message arrives, and so on. Authenticated with the shared token in
// private.settings ("x-meyouww-dispatch" header), not with a user JWT.
// Body: { user_id, data: { type, ... }, channel }
// Sends a data-only FCM message to every active device of that person. The payload
// carries IDs only; the app posts the notification and fetches details itself.





const TTL = "259200s"; // 3 days; the inbox keeps everything anyway

Deno.serve(async (req) => {
  if (req.method !== "POST") return json({ error: "method_not_allowed" }, 405);
  const token = req.headers.get("x-meyouww-dispatch") ?? "";
  if (token.length < 16 || token.length > 200) return json({ error: "unauthorized" }, 401);

  const db = adminClient();
  const { data: valid } = await db.rpc("check_dispatch_token", { p_token: token });
  if (valid !== true) return json({ error: "unauthorized" }, 401);
  if (!isFcmConfigured()) return json({ error: "push_not_configured" }, 503);

  const request = parseDispatch(await readJson(req));
  if (!request) return json({ error: "bad_request" }, 400);

  const { data: devices } = await db
    .from("devices")
    .select("id")
    .eq("user_id", request.userId)
    .is("revoked_at", null);
  const ids = (devices ?? []).map((d: { id: string }) => d.id);
  if (ids.length === 0) return json({ sent: 0, devices: 0 });

  const [{ data: tokens }, { data: states }] = await Promise.all([
    db.from("push_tokens").select("device_id, token").in("device_id", ids),
    db.from("device_state").select("device_id, notifications_enabled, channels").in("device_id", ids),
  ]);
  const stateOf = new Map((states ?? []).map((s: { device_id: string }) => [s.device_id, s]));

  let sent = 0;
  await Promise.all((tokens ?? []).map(async (t: { device_id: string; token: string }) => {
    // Every dispatched event leads to a visible notification unless the person turned it off.
    const priority = choosePriority(true, stateOf.get(t.device_id) as never, request.channel);
    const result = await sendDataMessage(t.token, request.data, priority, TTL);
    if (result.ok) sent++;
    else if (result.unregistered) await db.rpc("forget_push_token", { p_token: t.token });
  }));
  return json({ sent, devices: ids.length });
});
